## Defines the durations of the partials of an additive synthesis note. The fundamental lasts for#"duracionTotal". The rest of the partials' durations are equal to the total duration minus the#corresponding atack time.def partialsDurations(startTimesCSD, totalDuration):		durations	= []		for x in startTimesCSD:		oneDuration = x		oneDuration = totalDuration - x		durations.append(oneDuration)	return durations